// LookupRMISmelter finds a smelter by name (fuzzy match) and returns its RMI status.
func LookupRMISmelter(name string) *RMISmelter {
	name = normalizeSmelterName(name)
	for i := range RMISmelterList {
		if normalizeSmelterName(RMISmelterList[i].Name) == name {
			return &RMISmelterList[i]
		}
	}
	return nil
}

func normalizeSmelterName(s string) string {
	// Simple normalization: lowercase, trim spaces
	// In production, use Levenshtein distance or fuzzy matching
	return strings.ToLower(strings.TrimSpace(s))
}
